eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   programsList: () => (/* binding */ programsList)\n/* harmony export */ });\nconst programsList = [\n    {\n        slug: \"accessibility\",\n        title: \"Accessibility\",\n        image: \"/images/programs/program-accessibility.jpg\",\n        summary: \"Tearing down physical and infrastructural barriers across public transit, highway toilets, and community spaces.\",\n        fullContent: `Hazrat Nizamuddin railway station has been made accessible by Sangati, in collaboration with Yatra and Anuprayaas — a solution designed for both locomotor and visual disability. On 3 December 2020, International Day of Persons with Disabilities, we opened our first accessible public toilet in Sector 29, Gurgaon. We intend to set up at least a hundred more, covering every highway and knocking away every barrier we find.`,\n        highlights: [\n            \"Hazrat Nizamuddin Railway Station transformation for locomotor & visual disability\",\n            \"Accessible Public Toilet in Sector 29, Gurgaon launched 3 Dec 2020\",\n            \"Highway Accessibility Audit & 100 Accessible Toilets Drive\",\n            \"Ramp design, tactile paving, and Braille signage consulting\"\n        ],\n        keyStats: [\n            \"1 Central Railway Hub Transformed\",\n            \"100+ Toilet Campaign\",\n            \"3 Dec 2020 Launch\"\n        ],\n        partners: [\n            \"Yatra\",\n            \"Anuprayaas\"\n        ]\n    },\n    {\n        slug: \"mobility\",\n        title: \"Mobility\",\n        image: \"/images/programs/program-mobility.jpg\",\n        summary: \"Modified vehicles, folding ramps, accessible cabs, and Nomads on Wheels to unlock independent travel.\",\n        fullContent: `Modified vehicles, folding ramps, wheelchair-accessible cabs, and Nomads on Wheels — our campaign to make tourism across India genuinely reachable. Travel options, boarding, lodging, restaurants, markets, theatres, monuments: each one checked for accessibility and sensitised to the need.`,\n        highlights: [\n            \"Nomads on Wheels: Nationwide accessible tourism campaign\",\n            \"Custom vehicle retrofitting and hand-controls advocacy\",\n            \"Accessible transport directory: hotels, restaurants, theatres, monuments\",\n            \"Door-to-door wheelchair folding ramp provision\"\n        ],\n        keyStats: [\n            \"6,000 km Yatra Route Covered\",\n            \"100s of Verified Accessible Sites\",\n            \"24/7 Helpline Support\"\n        ],\n        partners: [\n            \"Nomads on Wheels\",\n            \"Sangati Mobility Network\"\n        ]\n    },\n    {\n        slug: \"health\",\n        title: \"Health & Critical Care\",\n        image: \"/images/programs/program-health.jpg\",\n        summary: \"Rural OPD care in Himachal Pradesh, cancer screening camps, COVID emergency relief, and medical aid.\",\n        fullContent: `Our critical care centre in Bathri, Dalhousie, Himachal Pradesh serves rural India with OPD treatment for 300 people every day, and medically assisted deliveries in growing numbers. Our March 2024 health and cancer-screening camp tested 140 people — 80 percent of them women — with mammography, pap smear, X-ray, ENT and physiological examination. A 2022 camp at the same centre reached more than 500 people from neighbouring villages.`,\n        highlights: [\n            \"Bathri Critical Care Centre: 300 OPD patients served daily\",\n            \"Medically assisted childbirth and maternal care in rural Himachal\",\n            \"March 2024 Cancer Screening: 140 patients (80% women) screened\",\n            \"COVID Relief: 500+ cooked meals daily & medical kit distribution across rural India\"\n        ],\n        keyStats: [\n            \"300 Daily OPD Patients\",\n            \"140 Cancer Screenings\",\n            \"500+ Fed Daily in COVID\"\n        ],\n        partners: [\n            \"Emosync\",\n            \"Rural Health Initiative Bathri\"\n        ]\n    },\n    {\n        slug: \"skills\",\n        title: \"Skill Development & Jobs\",\n        image: \"/images/programs/program-skills.jpg\",\n        summary: \"Project Udaan: Free tech skill training in web dev, Python, app design, laptop repair, DTP, and placement support.\",\n        fullContent: `Under Project Udaan, Sangati runs free skill training for persons with disability: website development, Python programming, mobile app design, laptop repair with CompTIA A+ certification, and DTP. Delivered online and at our centres in Gurgaon and Jodhpur, with partners including Codegeeko and JetKing. In 2023, 170 people were assessed for training. Our job portal helps candidates apply, prepare, interview and join — and stays with them after.`,\n        highlights: [\n            \"Project Udaan: Free certification in Web Dev, Python, DTP, & Laptop Repair (CompTIA A+)\",\n            \"Physical centers in Gurgaon & Jodhpur plus nationwide online learning\",\n            \"170 candidates assessed for specialized training in 2023 alone\",\n            \"Dedicated Job Portal launched on Independence Day for recruitment and ongoing mentorship\"\n        ],\n        keyStats: [\n            \"170 Assessed in 2023\",\n            \"2 Training Hubs\",\n            \"100% Free Tuition\"\n        ],\n        partners: [\n            \"Codegeeko\",\n            \"JetKing\",\n            \"Sh Praveen Vyas (Jodhpur Center)\"\n        ]\n    },\n    {\n        slug: \"livelihood\",\n        title: \"Livelihood & Entrepreneurship\",\n        image: \"/images/programs/program-livelihood.jpg\",\n        summary: \"Sangati Shoppe (संगTea) accessible street vendor carts and artisan product showcases for economic independence.\",\n        fullContent: `Sangati Shoppe is a mobile, accessible street vendor's cart — संगTea — designed so that a person with disability can run a business independently and with dignity. We have partnered with Evoo on VentureonWheels carts, and worked with NHFDC on handmade leather goods, file folders, wallets and decorative items made by our community.`,\n        highlights: [\n            \"संगTea / Sangati Shoppe: Custom ergonomic vendor cart for independent micro-entrepreneurs\",\n            \"VentureonWheels partnership with Evoo for mobile cart deployments\",\n            \"Handmade leather items, folders, wallets, and decor crafted by Divyang artisans\",\n            \"Exhibition support at Divyakala Mela with NHFDC\"\n        ],\n        keyStats: [\n            \"Independent Micro-Businesses\",\n            \"NHFDC Handicraft Partner\",\n            \"VentureonWheels Cart\"\n        ],\n        partners: [\n            \"NHFDC\",\n            \"Evoo (VentureonWheels)\"\n        ]\n    },\n    {\n        slug: \"sports-arts\",\n        title: \"Sports, Arts & Literature\",\n        image: \"/images/programs/program-sports.jpg\",\n        summary: \"Delhi Half-Marathon team, inclusive Chess Club, Down’s Syndrome caregiver handbooks, and autism spectrum literature.\",\n        fullContent: `Twenty-five of us ran the Vedanta Delhi Half-Marathon in October 2023 in the Champions with Disability segment. Our Chess Club, launched July 2024 with Archit Lakhani and Aakarsh Deepak Boswan of Gems Modern Academy Dubai, welcomes every skill level. Sangati also publishes books — a Down's Syndrome caregivers' handbook in Hindi and English, and Sangarsh… Sah Harsh, the story of Nehal, an artist and working woman on the autism spectrum, told by her mother Seema.`,\n        highlights: [\n            \"Vedanta Delhi Half-Marathon: 25 Divyang runners representing Sangati\",\n            \"Sangati Chess Club launched July 2024 with Gems Modern Academy Dubai\",\n            \"Down Syndrome Caregivers Handbook published in Hindi & English\",\n            \"Sangarsh... Sah Harsh book publishing Nehal’s story of autism, art, and career success\"\n        ],\n        keyStats: [\n            \"25 Half-Marathon Runners\",\n            \"Global Chess Club\",\n            \"2 Published Books\"\n        ],\n        partners: [\n            \"Gems Modern Academy Dubai\",\n            \"Archit Lakhani & Aakarsh Deepak Boswan\"\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./content/programs.ts\n");

